import { promises as fs } from "node:fs";
import path from "node:path";
import type { AdminActivityRecord, AdminErrorRecord, AdminTaskRecord } from "@/types/admin";

type StoredAdminTaskSnapshot = {
  generatedAt: string;
  tasks: AdminTaskRecord[];
  activities: AdminActivityRecord[];
};

type StoredAdminErrorEntry = {
  id: string;
  source: "security" | "system";
  title: string;
  detail: string;
  statusCode: number;
  severity: "medium" | "high";
  createdAt: string;
  meta?: Record<string, unknown>;
};

const ADMIN_LOGS_ROOT = path.join(process.cwd(), "backend", "logs");

function getMonthFolder(now = new Date()) {
  return `${now.getUTCFullYear()}-${String(now.getUTCMonth() + 1).padStart(2, "0")}`;
}

async function ensureMonthlyDir(category: "admin-tasks" | "admin-errors" | "admin-requests" | "admin-logins", now = new Date()) {
  const dir = path.join(ADMIN_LOGS_ROOT, category, getMonthFolder(now));
  await fs.mkdir(dir, { recursive: true });
  return dir;
}

export async function archiveAdminTaskSnapshot(snapshot: StoredAdminTaskSnapshot, now = new Date()) {
  const dir = await ensureMonthlyDir("admin-tasks", now);
  const filePath = path.join(dir, `tasks-${getMonthFolder(now)}.json`);
  await fs.writeFile(filePath, `${JSON.stringify(snapshot, null, 2)}\n`, "utf8");
  return filePath;
}

export async function archiveAdminRequestActivities(activities: AdminActivityRecord[], now = new Date()) {
  if (activities.length === 0) {
    return null;
  }

  const dir = await ensureMonthlyDir("admin-requests", now);
  const filePath = path.join(dir, `requests-${getMonthFolder(now)}.ndjson`);
  const lines = activities
    .filter((activity) => activity.method === "GET" || activity.method === "POST")
    .map((activity) => JSON.stringify(activity));

  if (lines.length === 0) {
    return null;
  }

  await fs.appendFile(filePath, `${lines.join("\n")}\n`, "utf8");
  return filePath;
}

export async function recordAdminLoginEntry(entry: {
  email: string;
  ok: boolean;
  statusCode: number;
  role?: string | null;
  createdAt: string;
  reason?: string;
}, now = new Date()) {
  const dir = await ensureMonthlyDir("admin-logins", now);
  const filePath = path.join(dir, `logins-${getMonthFolder(now)}.ndjson`);
  await fs.appendFile(filePath, `${JSON.stringify(entry)}\n`, "utf8");
  return filePath;
}

export async function recordAdminErrorEntry(entry: StoredAdminErrorEntry, now = new Date()) {
  const dir = await ensureMonthlyDir("admin-errors", now);
  const filePath = path.join(dir, `errors-${getMonthFolder(now)}.ndjson`);
  await fs.appendFile(filePath, `${JSON.stringify(entry)}\n`, "utf8");
  return filePath;
}

export async function readRecentAdminErrorEntries(limit = 20) {
  const errorsRoot = path.join(ADMIN_LOGS_ROOT, "admin-errors");
  try {
    const monthDirs = (await fs.readdir(errorsRoot, { withFileTypes: true }))
      .filter((entry) => entry.isDirectory())
      .map((entry) => entry.name)
      .sort()
      .slice(-3);

    const rows: StoredAdminErrorEntry[] = [];
    for (const monthDir of monthDirs) {
      const filePath = path.join(errorsRoot, monthDir, `errors-${monthDir}.ndjson`);
      try {
        const raw = await fs.readFile(filePath, "utf8");
        for (const line of raw.split("\n")) {
          const trimmed = line.trim();
          if (!trimmed) {
            continue;
          }
          rows.push(JSON.parse(trimmed) as StoredAdminErrorEntry);
        }
      } catch {
        // Ignore missing month files.
      }
    }

    return rows
      .sort((left, right) => new Date(right.createdAt).getTime() - new Date(left.createdAt).getTime())
      .slice(0, limit)
      .map<AdminErrorRecord>((entry) => ({
        id: entry.id,
        source: "system",
        title: entry.title,
        detail: entry.detail,
        statusCode: entry.statusCode,
        severity: entry.severity,
        createdAt: entry.createdAt,
        href: "/admin/errors",
      }));
  } catch {
    return [];
  }
}
